package com.javaroadmap.algo.complexity;

public class App {
    public static long sumLinear(long n) {
        long sum = 0;
        for (long i = 1; i <= n; i++) sum += i;
        return sum;
    }
    public static long sumConstant(long n) {
        return n * (n + 1) / 2;
    }
    public static void main(String[] args) {
        System.out.println("线性累加 O(n) 结果：" + sumLinear(1000L));
        System.out.println("数学公式 O(1) 结果：" + sumConstant(1000L));
    }
}

package com.javaroadmap.algo.recursion;

public class App {
    public static int sumByLoop(int n) {
        int res = 0;
        for (int i = 1; i <= n; i++) res += i;
        return res;
    }
    public static int sumByRecursion(int n) {
        if (n <= 1) return n;
        return n + sumByRecursion(n - 1);
    }
    public static void main(String[] args) {
        System.out.println("迭代求和(1..10)：" + sumByLoop(10));
        System.out.println("递归求和(1..10)：" + sumByRecursion(10));
    }
}

