    public static int logOrder(int n) {
        int count = 0;
        while (n > 1) { n /= 2; count++; }
        return count;
    }
    public static void main(String[] args) {
        System.out.println("O(log n) 折半步数(n=16)：" + logOrder(16));
    }
}

package com.javaroadmap.algo.space;

public class App {
    public static int constantSpace(int[] arr) {
        int maxVal = Integer.MIN_VALUE;
        for (int v : arr) if (v > maxVal) maxVal = v;
        return maxVal;
    }
    public static void main(String[] args) {
        System.out.println("O(1) 辅助空间最大值：" + constantSpace(new int[]{3, 7, 2, 9, 5}));
    }
}

